class Solution {
public:
    int countOrders(int n) {
        long long ans = 1, MOD = 1000000007;
        for (int i = 1; i <= n; ++i) {
            ans = (ans * i) % MOD;
            ans = (ans * (2 * i - 1)) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int countOrders(int n) {
        long ans = 1, MOD = 1_000_000_007;
        for (int i = 1; i <= n; i++) {
            ans = (ans * i) % MOD;
            ans = (ans * (2 * i - 1)) % MOD;
        }
        return (int)ans;
    }
}

var countOrders = function(n) {
    let ans = 1n, MOD = 1000000007n;
    for (let i = 1n; i <= BigInt(n); i++) {
        ans = (ans * i * (2n * i - 1n)) % MOD;
    }
    return Number(ans);
};
